<template>
  <!-- Sektions-Auszeichnung über den Überschriften: ein feines Strichsymbol in
       Blau, daneben die Zeile in gemischtem Satz. Die Symbole und die
       Strichstärke stammen aus dem Bestand – dieselbe Sprache führen die
       Karten der Seite.
       Schriftgrad als clamp, Symbolgröße und Innenabstand in em: die Zeile
       hält damit auf jedem Gerät dasselbe Verhältnis zur Überschrift, die
       ihrerseits fluide ist. -->
  <span
    v-if="!pill"
    class="eyebrow inline-flex items-center gap-[0.6em] text-[clamp(0.74rem,0.6375rem+0.436vw,0.92rem)] font-semibold"
    :class="dark ? 'text-white/[0.92]' : 'text-navy'"
  >
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9"
         class="shrink-0 w-[1.22em] h-[1.22em]" :class="dark ? 'text-[#5fa0ea]' : 'text-blue'">
      <path v-for="(d, i) in symbol" :key="i" stroke-linecap="round" stroke-linejoin="round" :d="d" />
    </svg>
    <slot />
  </span>

  <!-- Die Pille bleibt den Hero-Bereichen vorbehalten: dort steht die
       Auszeichnung allein auf der Navy-Fläche und führt keine Überschrift an,
       sondern trägt sich selbst. `wide` weitet die Polsterung im Hero. -->
  <span
    v-else
    class="inline-flex items-center gap-2 text-[13px] font-semibold tracking-[0.01em] py-[6px] rounded-full"
    :class="[
      wide ? 'px-[22.4px]' : 'px-[14px]',
      dark ? 'text-white bg-white/[0.08] border border-white/[0.14]' : 'text-navy bg-navy/[0.06]'
    ]"
  >
    <span class="w-[7px] h-[7px] rounded-full shrink-0" :class="dark ? 'bg-green' : 'bg-blue'"></span>
    <slot />
  </span>
</template>

